@extends('layouts.app') @section('title','Boutique') @section('content')<h1>La boutique</h1><form class="filters" method="get"><input name="q" value="{{ request('q') }}" placeholder="Rechercher un produit"><select name="category"><option value="">Toutes les catégories</option>@foreach($categories as $c)<option value="{{ $c->id }}" @selected(request('category')==$c->id)>{{ $c->name }}</option>@endforeach</select><input name="min" type="number" step=".01" placeholder="Prix min" value="{{ request('min') }}"><input name="max" type="number" step=".01" placeholder="Prix max" value="{{ request('max') }}"><select name="sort"><option value="">Plus récents</option><option value="price_asc" @selected(request('sort')==='price_asc')>Prix croissant</option><option value="price_desc" @selected(request('sort')==='price_desc')>Prix décroissant</option></select><button class="btn">Filtrer</button></form><div class="grid">@forelse($products as $p)<article class="product"><a href="{{ route('products.show',$p) }}"><div class="photo">@if($p->image)<img src="{{ asset('storage/'.$p->image) }}" alt="{{ $p->name }}">@else<span>SN</span>@endif</div><small>{{ $p->category?->name }}</small><h3>{{ $p->name }}</h3></a><strong>{{ number_format((float)$p->price($currency),2) }} {{ $currency }}</strong><p class="muted">{{ $p->stock }} en stock</p><form method="post" action="{{ route('cart.add',$p) }}">@csrf<button class="btn small" @disabled(!$p->stock)>Ajouter au panier</button></form></article>@empty<p>Aucun résultat trouvé.</p>@endforelse</div><div class="pagination">{{ $products->links() }}</div>@endsection
